replace('format!("(fwp_r{}){{{{{}}}}}", n, fs.join(", "))','''let values: Vec<_> = fs.into_iter().zip(abi.result_numbers(fg.g.prog, id))\n                    .map(|(v, n)| n.map_or_else(|| v.clone(), |n| n.decode_word(&v))).collect();\n                format!("(fwp_wr{id}){{{}}}", values.join(", "))''')
