replace('        let call = format!("w{}({})", id, args.join(", "));','''        let args = abi.args_decode_words(self.prog, id, args);\n        let call = format!("w{}({})", id, args.join(", "));''')
replace('                let fields: Vec<_> = record_fields(&self.prog.shapes, &ty)','                let values = abi.result_words(self.prog, id, "r");\n                let fields: Vec<_> = record_fields(&self.prog.shapes, &ty)')
replace('.map(|(i, (_, ty))| (format!("r.f[{i}]"), ty.clone()))','.map(|(i, (_, ty))| (values[i].clone(), ty.clone()))')
replace('format!("{pre}fwp_r{n} r = {call}; {post}{protect} V result = {}; {finish}return result;",\n                    self.fresh(format!("fwp_record({n}, r.f)")))','''format!("{pre}fwp_wr{id} r = {call}; {post}{protect} V result = {}; {finish}return result;",\n                    self.fresh(format!("fwp_record({n}, {})", FnGen::array(&values))))''')
replace('            (None, None) => format!("{}V r = {}; {}return r;", pre, call, post),','''            (None, None) => {\n                let value = abi.scalar_result(self.prog, id).map_or_else(|| call.clone(), |n| n.to_word(&call));\n                format!("{pre}V r = {value}; {post}return r;")\n            },''')
replace('    // records returned in registers, and the workers that return them','    // C aggregate worker results; the target ABI chooses their register classes.')
replace('    for (id, abi) in g.abis.iter().enumerate() {\n        if let Some(abi) = abi.as_ref().filter(|_| live[id]) {','''    for (id, abi) in g.abis.iter().enumerate() {\n        if let Some(abi) = abi.as_ref().filter(|a| live[id] && a.ret.is_some()) {\n            let fields: Vec<_> = abi.result_numbers(prog, id).into_iter().enumerate()\n                .map(|(i, n)| format!("{} f{i};", n.map_or_else(|| "V".into(), NativeNumber::c_type))).collect();\n            let _ = writeln!(out, "typedef struct {{ {} }} fwp_wr{id};", fields.join(" "));\n        }\n    }\n    for (id, abi) in g.abis.iter().enumerate() {\n        if let Some(abi) = abi.as_ref().filter(|_| live[id]) {''')
